REVOKE DELETE ON public.reviews FROM authenticated;
CREATE OR REPLACE FUNCTION public.audit_claim_submission() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.directory_audit(business_id,entity_id,actor_id,action,note,after_data) VALUES(NEW.business_id,NEW.id,auth.uid(),'claim_submitted','Ownership review requested',jsonb_build_object('state',NEW.status)); RETURN NEW; END; $$;
CREATE TRIGGER audit_claim_submit AFTER INSERT ON public.business_claims FOR EACH ROW EXECUTE FUNCTION public.audit_claim_submission();
CREATE OR REPLACE FUNCTION public.check_claim_evidence_exists() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM unnest(NEW.evidence) p WHERE NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='trust-evidence' AND name=p)) THEN RAISE EXCEPTION 'Claim evidence file unavailable'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER check_claim_evidence BEFORE INSERT OR UPDATE ON public.business_claims FOR EACH ROW EXECUTE FUNCTION public.check_claim_evidence_exists();
CREATE OR REPLACE FUNCTION public.change_listing_trust(bid uuid,patch jsonb,decision_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF length(trim(decision_reason))<5 OR NOT public.has_permission('listings.moderate',bid) THEN RAISE EXCEPTION 'Listing decision requires permission and a reason'; END IF; IF EXISTS(SELECT 1 FROM jsonb_object_keys(patch) k WHERE k NOT IN ('status','plan','requested_plan','sponsored','owner_feedback')) THEN RAISE EXCEPTION 'Unsupported trust change'; END IF; IF (patch?'plan' OR patch?'sponsored' OR patch?'requested_plan') AND NOT public.has_permission('entitlements.manage',bid) THEN RAISE EXCEPTION 'Entitlement changes require super admin'; END IF; PERFORM set_config('app.trust_authorized','true',true); PERFORM set_config('app.trust_reason',decision_reason,true); UPDATE public.businesses SET status=coalesce(patch->>'status',status),plan=coalesce(patch->>'plan',plan),sponsored=coalesce((patch->>'sponsored')::boolean,sponsored),requested_plan=CASE WHEN patch?'requested_plan' THEN patch->>'requested_plan' ELSE requested_plan END,owner_feedback=coalesce(patch->>'owner_feedback',owner_feedback) WHERE id=bid; IF NOT FOUND THEN RAISE EXCEPTION 'Listing unavailable'; END IF; END; $$;
GRANT EXECUTE ON FUNCTION public.change_listing_trust(uuid,jsonb,text) TO authenticated; REVOKE EXECUTE ON FUNCTION public.change_listing_trust(uuid,jsonb,text) FROM PUBLIC,anon;